input.command:
ls '/Users/sinchunyeung/github/firstmate/state/fm-design-config-crew-dispatch-json-profile-04.inbox'/*.msg 2>/dev/null || echo 'inbox empty'
mkdir -p /tmp/fm-dispatch-04
cat > /tmp/fm-dispatch-04/crew-dispatch.json <<'EOF'
{
  "rules": [
    {
      "when": "The task is UI-facing or visual-design work: frontend styling, layout, HTML/CSS notes chrome, product UI presentation, Lavish artifact design, or a visual review of pages, screenshots, or UI. Includes paper2notes visual HTML notes design. Does not include backend or pipeline work that merely emits images (PDF crop regeneration, classification scripts) unless the task itself is a visual review.",
      "use": [
        {
          "harness": "cursor",
          "model": "claude-fable-5-1-thinking-xhigh"
        },
        {
          "harness": "claude",
          "model": "fable",
          "effort": "xhigh"
        }
      ],
      "why": "Captain: UI/visual/design work routes to the Fable family. Cursor id claude-fable-5-1-thinking-xhigh is this home's proven Book 5 design-overhaul spawn. Claude alias fable at effort xhigh is the same family on the Claude quota window. Cursor has no verified effort flag, so the thinking level is in the model id. Resolve the pair through quota-array-dispatch."
    },
    {
      "when": "The task is simpler or routine: config edits, small targeted fixes, linguist/gitattributes, a thin CI workflow, docs-only copy, status busywork, or a narrow well-specified investigation with an explicit path.",
      "use": [
        {
          "harness": "claude",
          "model": "sonnet",
          "effort": "medium"
        },
        {
          "harness": "cursor",
          "model": "cursor-grok-4.6-high"
        }
      ],
      "why": "Captain: simpler/routine work routes to Sonnet or Grok. Standalone grok CLI is not installed and grok auth is unusable, so Grok is Cursor catalog id cursor-grok-4.6-high. Sonnet is Claude's documented alias so the array spans Claude all_models vs Cursor. Resolve the pair through quota-array-dispatch."
    },
    {
      "when": "The task is substantial non-visual coding or an ambiguous non-visual investigation: multi-file features, pipelines, algorithm or CI-gate work, OCR/intake plumbing, diagnosis or planning scouts that are not a visual review, or Firstmate shared-tooling changes.",
      "use": [
        {
          "harness": "claude",
          "model": "sonnet",
          "effort": "xhigh"
        },
        {
          "harness": "cursor",
          "model": "cursor-grok-4.6-xhigh"
        }
      ],
      "why": "Inferred from this home's backlog, not a captain-stated family change: paper2db pipeline/crop ships, SOTS CI/bench, OCR intake, and firstmate design scouts are common and are not UI design. Keep the captain's Sonnet-or-Grok families at xhigh."
    }
  ],
  "default": [
    {
      "harness": "claude",
      "model": "sonnet",
      "effort": "xhigh"
    },
    {
      "harness": "cursor",
      "model": "cursor-grok-4.6-xhigh"
    }
  ]
}
EOF
echo '===== jq . ====='
jq . /tmp/fm-dispatch-04/crew-dispatch.json >/dev/null && echo 'jq: valid JSON'
echo '===== bootstrap-equivalent validation ====='
err=$(jq -r '
    def verified($h): ["claude","codex","opencode","pi","pi-signed","grok","kimi","cursor","agy","muse","rovo","omp"] | index($h);
    def effort_ok($h; $m; $e):
      if $e == null then true
      elif ($e | type) != "string" then false
      elif $e == "ultra" then (($h == "pi" or $h == "pi-signed") and (($m | type) == "string") and ($m | startswith("codex-native/")) and ($m | length) > 13)
      elif $h == "claude" then (["low","medium","high","xhigh","max"] | index($e))
      elif $h == "codex" then ((["low","medium","high","xhigh"] | index($e)) != null or ($e == "max" and $m == "gpt-5.6-luna"))
      elif $h == "grok" then (["low","medium","high"] | index($e))
      elif $h == "agy" then (["low","medium","high"] | index($e))
      elif $h == "pi" or $h == "pi-signed" or $h == "omp" then (["low","medium","high","xhigh","max"] | index($e))
      elif $h == "muse" then (["low","medium","high","xhigh","max"] | index($e))
      elif $h == "rovo" then (["low","medium","high","max"] | index($e))
      elif $h == "opencode" or $h == "kimi" or $h == "cursor" then false
      else true
      end;
    def profiles($value):
      if ($value | type) == "array" then $value
      elif ($value | type) == "object" then [$value]
      else []
      end;
    def configured_profiles:
      ([(.rules // [])[]? | profiles(.use?)[]?]
        + (if has("default") then [profiles(.default)[]?] else [] end));
    def malformed_optional_fields($items):
      ($items | any(has("model") and (((.model | type) != "string") or (.model | length) == 0)))
      or ($items | any(has("effort") and (((.effort | type) != "string") or (.effort | length) == 0)));
    def bad_efforts:
      configured_profiles
      | map({h: .harness, m: .model, e: .effort})
      | map(select(.e != null))
      | map(select((.h | type) == "string" and verified(.h)))
      | map(select(. as $p | effort_ok($p.h; $p.m; $p.e) | not))
      | map("\(.h):\(.e)")
      | unique;
    if type != "object" then "top-level value must be an object"
    elif has("rules") and (.rules | type) != "array" then "rules must be an array"
    elif [(.rules // [])[]? | select(type != "object")] | length > 0 then "each rule must be an object"
    elif [(.rules // [])[]? | select((.when? | type) != "string" or (.when | length) == 0)] | length > 0 then "each rule needs non-empty when"
    elif [(.rules // [])[]? | select((.use? | type) != "object" and (.use? | type) != "array")] | length > 0 then "each rule needs use"
    elif [(.rules // [])[]? | select((.use? | type) == "array" and (.use | length) == 0)] | length > 0 then "each rule needs at least one use profile"
    elif [(.rules // [])[]? | profiles(.use?)[]? | select(type != "object")] | length > 0 then "each use profile must be an object"
    elif [(.rules // [])[]? | profiles(.use?)[]? | select((.harness? | type) != "string" or (.harness | length) == 0)] | length > 0 then "each use profile needs harness"
    elif malformed_optional_fields([(.rules // [])[]? | profiles(.use?)[]?]) then "use profile model and effort must be non-empty strings when present"
    elif [(.rules // [])[]? | select(has("select") and ((.select? | type) != "string" or (.select | length) == 0))] | length > 0 then "select must be a non-empty string"
    elif [(.rules // [])[]? | .select? // empty | select(. != "quota-balanced")] | length > 0 then
      "unknown select: " + ([ (.rules // [])[]? | .select? // empty | select(. != "quota-balanced") ] | unique | join(", "))
    elif has("default") and ((.default | type) != "object" and (.default | type) != "array") then "default must be a profile object or non-empty profile array"
    elif has("default") and ((.default | type) == "array" and (.default | length) == 0) then "default needs at least one profile"
    elif has("default") and ([profiles(.default)[]? | select(type != "object")] | length) > 0 then "each default profile must be an object"
    elif has("default") and ([profiles(.default)[]? | select((.harness? | type) != "string" or (.harness | length) == 0)] | length) > 0 then "each default profile needs harness"
    elif has("default") and malformed_optional_fields([profiles(.default)[]?]) then "default profile model and effort must be non-empty strings when present"
    else
      (configured_profiles
        | map(.harness)
        | map(select(. != null))
        | map(select(. as $h | verified($h) | not))
        | unique) as $bad_harnesses
      | if ($bad_harnesses | length) > 0 then "unverified harness: " + ($bad_harnesses | join(", "))
        elif (bad_efforts | length) > 0 then "invalid effort: " + (bad_efforts | join(", "))
        else empty
        end
    end
  ' /tmp/fm-dispatch-04/crew-dispatch.json)
if [ -n "$err" ]; then echo "INVALID: $err"; else echo 'bootstrap validator: ok (empty error)'; fi
echo '===== profile summary ====='
jq -r '
    def profile($p):
      ($p.harness | tostring)
      + (if ($p.model? != null) then "/" + ($p.model | tostring)
         elif ($p.effort? != null) then "/default"
         else "" end)
      + (if ($p.effort? != null) then "/" + ($p.effort | tostring) else "" end);
    def profile_set($value; $selector):
      if ($value | type) == "array" then
        (($selector // "quota-balanced") + "[" + ([$value[] | profile(.)] | join(", ")) + "]")
      else profile($value)
      end;
    (["crew dispatch active"]
      + [(.rules // [])[]? | "rule: " + (.when | tostring[0:80]) + "... -> " + profile_set(.use; .select?)]
      + (if has("default") then ["default: " + profile_set(.default; null)] else [] end))
    | .[]
  ' /tmp/fm-dispatch-04/crew-dispatch.json
